def repair_treasury_repayments_of_unwithdrawn_advances(apps, schema_editor):
    """Client correction 2026-10-11: a company advance repaid "in cash"
    before it was ever withdrawn put money into treasury that had never
    left it. Treasury may only get back what was really withdrawn: any
    TREASURY repayment beyond amount_drawn becomes a CANCEL (no money
    moves) and its MONEY_IN is reduced or removed."""
    from decimal import Decimal

    ContentType = apps.get_model("contenttypes", "ContentType")
    ShareholderLoan = apps.get_model("finance", "ShareholderLoan")
    Repayment = apps.get_model("finance", "ShareholderLoanRepayment")
    TreasuryTransaction = apps.get_model("finance", "TreasuryTransaction")
    repayment_ct = ContentType.objects.filter(
        app_label="finance", model="shareholderloanrepayment"
    ).first()

    for loan in ShareholderLoan.objects.filter(source="COMPANY"):
        cash_back = list(Repayment.objects.filter(loan=loan, method="TREASURY").order_by("-id"))
        excess = sum((r.amount for r in cash_back), Decimal("0")) - loan.amount_drawn
        cancelled = Decimal("0")
        for repayment in cash_back:
            if excess <= 0:
                break
            moved = min(excess, repayment.amount)
            txns = TreasuryTransaction.objects.filter(
                source_content_type=repayment_ct, source_object_id=repayment.id, type="MONEY_IN"
            ) if repayment_ct else TreasuryTransaction.objects.none()
            if moved == repayment.amount:
                txns.delete()
                repayment.method = "CANCEL"
                repayment.bank_account_id = None
                repayment.cash_account_id = None
                repayment.notes = (repayment.notes + " " if repayment.notes else "") + (
                    "(corrige : avance jamais retiree, aucun mouvement de caisse)"
                )
                repayment.save()
            else:
                for txn in txns:
                    txn.amount = txn.amount - moved
                    txn.save(update_fields=["amount"])
                repayment.amount = repayment.amount - moved
                repayment.save(update_fields=["amount"])
                Repayment.objects.create(
                    loan=loan, method="CANCEL", amount=moved, date=repayment.date,
                    notes="(corrige : part jamais retiree, aucun mouvement de caisse)",
                    recorded_by_id=repayment.recorded_by_id,
                )
            excess -= moved
            cancelled += moved
        if cancelled:
            loan.amount_cancelled = cancelled
            loan.save(update_fields=["amount_cancelled"])


